const state={pipelines:[],current:null,config:null,stores:[],aiProvider:null,objectStorage:null,account:null,team:{members:[],roles:{}},operations:null,productCatalog:{summary:{},products:[]},marketResearch:{summary:{},candidates:[],rules:null},researchSearch:'',researchDecisionFilter:'all',researchCandidateId:null,selectedCatalogIds:new Set(),supplierMonitor:{summary:{},products:[]},supplierMonitorJob:null,supplierMonitorTimer:null,batchProcessJob:null,batchProcessTimer:null,batchProcessHistoryMode:false,versionPipelineId:null,assetLibrary:{summary:{},assets:[]},activity:[],notifications:{notifications:[],unread_count:0},dashboard:{counters:{},issues:[]},batchImportJob:null,batchImportTimer:null,dialogStage:null,imageSelection:[],pipelineSearch:'',pipelineFilter:'all',taskFilter:'all',catalogSearch:'',catalogStatusFilter:'all',assetSearch:'',assetTypeFilter:'all',assetStatusFilter:'all'};
