const $=selector=>document.querySelector(selector);
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const raw=await response.text();let data;try{data=raw?JSON.parse(raw):{}}catch{const preview=raw.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,160);throw new Error(`HTTP ${response.status} 返回非 JSON${preview?`：${preview}`:''}`)}if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(el.timer);el.timer=setTimeout(()=>el.className='toast',3500)}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function stageStatus(pipeline,n){return pipeline?.stages?.[String(n)]?.status||'LOCKED'}
function formatDate(value){if(!value)return '—';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value);return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)}
function hasPermission(permission){return(state.account?.identity?.permissions||[]).includes(permission)}
function canRun(n){if(stageStatus(state.current,n)==='RUNNING')return false;const permission=n===1?'pipeline.create':n===3?'images.manage':n===5?'listing.publish':'stage.run';if(!hasPermission(permission))return false;if(n===1)return true;if(n===2&&!state.stores.length)return false;return stageStatus(state.current,n-1)==='PASS'}
function selectedStoreId(){return state.current?.store_id||state.stores[0]?.store_id||''}
function storeOptions(selected=selectedStoreId()){if(!state.stores.length)return '<option value="">请先授权 OZON 店铺</option>';return state.stores.map(store=>`<option value="${escapeHtml(store.store_id)}" ${store.store_id===selected?'selected':''}>${escapeHtml(store.name)} · ${escapeHtml(store.currency_code)}</option>`).join('')}
function pipelineBucket(p){const values=Object.values(p.stages||{}).map(stage=>stage.status);const done=values.filter(status=>status==='PASS').length;if(done===5)return'completed';if(values.includes('RUNNING'))return'running';if(values.includes('FAIL'))return'failed';return'draft'}
function renderList(){const root=$('#pipelineList');const query=state.pipelineSearch.toLowerCase();const filtered=state.pipelines.filter(p=>(!query||String(p.title_zh||'').toLowerCase().includes(query))&&(state.pipelineFilter==='all'||pipelineBucket(p)===state.pipelineFilter));$('#pipelineCount').textContent=`${filtered.length} / ${state.pipelines.length} 个任务`;if(!filtered.length){root.innerHTML=`<div class="empty">${state.pipelines.length?'没有符合标题条件的商品任务。':'暂无商品任务，输入 1688 商品 ID 开始。'}</div>`;return}root.innerHTML=filtered.map(p=>{const done=Object.values(p.stages||{}).filter(s=>s.status==='PASS').length;const bucket=pipelineBucket(p);const bucketName={completed:'已完成',failed:'需要处理',running:'运行中',draft:'处理中'}[bucket];const title=p.title_zh||'正在读取商品标题';return `<div class="pipeline-item ${state.current?.pipeline_id===p.pipeline_id?'active':''}" data-id="${escapeHtml(p.pipeline_id)}"><span class="pipeline-dot ${done===5?'done':''}"></span><span class="pipeline-info"><b title="${escapeHtml(title)}">${escapeHtml(title)}</b><small>1688 · ${escapeHtml(p.pipeline_id)} · ${formatDate(p.updated_at)} · ${bucketName}</small></span><span class="pipeline-progress">${done}/5</span></div>`}).join('');root.querySelectorAll('.pipeline-item').forEach(el=>el.onclick=()=>selectPipeline(el.dataset.id))}
function renderDetail(){if(!state.current){$('#emptyState').classList.remove('hidden');$('#detail').classList.add('hidden');return}$('#emptyState').classList.add('hidden');$('#detail').classList.remove('hidden');$('#productId').textContent=`1688 · ${state.current.pipeline_id}`;$('#productTitle').textContent=state.current.title_zh||'商品上架流水线';const selected=state.stores.find(store=>store.store_id===state.current.store_id);const statuses=stages.map(stage=>stageStatus(state.current,stage.n));const done=statuses.filter(status=>status==='PASS').length;const failed=statuses.includes('FAIL');const running=statuses.includes('RUNNING');const overall=$('#overallState');overall.textContent=failed?'需要处理':running?'正在运行':done===5?'上架完成':`${done}/5 已通过`;overall.className=`health-pill ${failed?'bad':running?'running':done===5?'good':''}`;$('#progressMetric').textContent=`${done} / 5`;$('#progressHint').textContent=done===5?'全部阶段已通过':failed?'存在门禁失败':`下一步：阶段 ${Math.min(done+1,5)}`;$('#storeMetric').textContent=selected?selected.name:state.stores.length?`${state.stores.length} 个店铺`:'未授权';$('#modeMetric').textContent=state.config?.dry_run?'DRY RUN':'LIVE';$('#modeHint').textContent=state.config?.dry_run?'安全预演，不提交':'允许真实提交';$('#updatedMetric').textContent=formatDate(state.current.updated_at);$('#configStrip').innerHTML=`<span><b>运行模式</b> ${state.config?.dry_run?'DRY RUN · 安全预演':'LIVE · 允许真实提交'}</span><span><b>OZON 店铺</b> ${selected?escapeHtml(selected.name):state.stores.length?`${state.stores.length} 个已授权 · 尚未选择`:'未授权'}</span><span><b>任务目录</b> work/${escapeHtml(state.current.pipeline_id)}/</span>`;$('#stageGrid').innerHTML=stages.map(s=>{const status=stageStatus(state.current,s.n);const artifact=state.current.artifacts?.[String(s.n)];return `<article class="stage stage-${status.toLowerCase()}"><div class="stage-number">0${s.n}<span class="status ${status.toLowerCase()}">${status}</span></div><h3>${s.title}</h3><p>${s.desc}</p><div class="stage-actions"><button data-run="${s.n}" ${canRun(s.n)?'':'disabled'}>${status==='LOCKED'?'开始运行':status==='RUNNING'?'运行中':'重新运行'}</button>${artifact?`<button class="view" data-view="${s.n}">查看产物</button>`:''}${s.n===1&&artifact?'<button class="view" data-images>管理图片</button>':''}</div></article>`}).join('');document.querySelectorAll('[data-run]').forEach(button=>button.onclick=()=>openStage(Number(button.dataset.run)));document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>viewArtifact(Number(button.dataset.view)));document.querySelectorAll('[data-images]').forEach(button=>button.onclick=openImages);const issues=(state.dashboard.issues||[]).filter(issue=>String(issue.pipeline_id)===String(state.current.pipeline_id));const card=$('#diagnosisCard');card.classList.toggle('hidden',!issues.length);$('#diagnosisCount').textContent=`${issues.length} 项`;$('#diagnosisList').innerHTML=issues.map(issue=>`<article class="diagnosis-item"><span class="diagnosis-tag">${escapeHtml(issue.category)}</span><div class="diagnosis-body"><b>阶段 ${issue.stage} · ${escapeHtml(issue.message)}</b><span>建议：${escapeHtml(issue.suggestion)}</span></div><button class="diagnosis-action" data-diagnosis-stage="${issue.stage}">打开阶段</button></article>`).join('');document.querySelectorAll('[data-diagnosis-stage]').forEach(button=>button.onclick=()=>openStage(Number(button.dataset.diagnosisStage)))}

