function renderImageGallery(){const selected=state.imageSelection.filter(item=>item.action!=='exclude').length;const aiCalls=state.imageSelection.reduce((sum,item)=>sum+(item.action==='reference_8'?8:item.action==='sku_main'?1:0),0);const translateCalls=state.imageSelection.filter(item=>item.action==='translate').length;$('#imageSelectionCount').textContent=`已处理 ${selected} / ${state.imageSelection.length} 张 · AI 生图 ${aiCalls} 次 · 翻译 ${translateCalls} 次`;$('#imageGallery').innerHTML=state.imageSelection.map((item,index)=>`<article class="image-card ${item.action!=='exclude'?'selected':'removed'}"><img src="${escapeHtml(item.url)}" alt="${escapeHtml(roleName(item.source_role))}" loading="lazy" referrerpolicy="no-referrer"><div class="image-card-body"><span>${escapeHtml(roleName(item.source_role))}${item.sku_id?` · SKU ${escapeHtml(item.sku_id)}`:''}</span><small>${escapeHtml(item.width||'?')} × ${escapeHtml(item.height||'?')} · ${escapeHtml(actionName(item.action))}</small><select class="image-action" data-image-index="${index}"><option value="exclude" ${item.action==='exclude'?'selected':''}>排除，不处理</option><option value="translate" ${item.action==='translate'?'selected':''}>俄语翻译 → Rich Content</option><option value="reference_8" ${item.action==='reference_8'?'selected':''}>作为参考生成共用八图</option>${item.source_role==='sku_image'?`<option value="sku_main" ${item.action==='sku_main'?'selected':''}>生成 SKU 专属主图</option>`:''}</select></div></article>`).join('');document.querySelectorAll('[data-image-index]').forEach(select=>select.onchange=()=>{const index=Number(select.dataset.imageIndex);if(select.value==='reference_8')state.imageSelection.forEach((item,itemIndex)=>{if(itemIndex!==index&&item.action==='reference_8')item.action='exclude'});state.imageSelection[index].action=select.value;renderImageGallery()})}
async function openImages(){try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/images`);state.imageSelection=result.images||[];renderImageGallery();$('#imagesDialog').showModal()}catch(error){toast(error.message,true)}}
async function saveImages(){try{const imagePlan=state.imageSelection.map(item=>({url:item.url,action:item.action}));const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/images`,{method:'POST',body:JSON.stringify({image_plan:imagePlan})});state.imageSelection=result.images||[];$('#imagesDialog').close();await selectPipeline(state.current.pipeline_id);toast(`图片方案已保存：AI 生图 ${result.estimated_ai_calls} 次，翻译 ${result.estimated_translation_calls} 次`)}catch(error){toast(error.message,true)}}
