async function deleteExternalAlerts(){if(!confirm('确认删除企业微信和邮件通知配置？发送历史也会删除。'))return;try{await api('/api/alert-channels',{method:'DELETE'});renderExternalAlerts({});$('#externalAlertsDialog').close();toast('外部通知配置已删除')}catch(error){toast(error.message,true)}}
function catalogStatusName(value){return{published:'已上架',ready:'待上架',needs_update:'需要更新',failed:'门禁失败',processing:'处理中',draft:'草稿'}[value]||value}
function catalogPrice(item){if(!item.price_min)return'—';const currency=item.currency_code||'';return item.price_min===item.price_max?`${item.price_min} ${currency}`:`${item.price_min}–${item.price_max} ${currency}`}
function filteredCatalog(){const query=state.catalogSearch.toLowerCase();return(state.productCatalog.products||[]).filter(item=>{if(state.catalogStatusFilter!=='all'&&item.status!==state.catalogStatusFilter)return false;if(!query)return true;return`${item.pipeline_id||''} ${item.title_zh||''} ${item.title_ru||''} ${(item.offer_ids||[]).join(' ')} ${item.store_id||''}`.toLowerCase().includes(query)})}
function updateCatalogSelection(){const rows=filteredCatalog();const selected=state.selectedCatalogIds.size;$('#batchProcessBtn').textContent=`批量处理（${selected}）`;$('#batchEditBtn').textContent=`批量编辑（${selected}）`;$('#supplierMonitorBtn').textContent=`供应商检测（${selected}）`;const disabled=!selected||!hasPermission('stage.run');$('#batchProcessBtn').disabled=disabled;$('#batchEditBtn').disabled=disabled;$('#supplierMonitorBtn').disabled=!selected||!hasPermission('pipeline.create');const all=rows.length>0&&rows.every(item=>state.selectedCatalogIds.has(String(item.pipeline_id)));$('#catalogSelectAll').checked=all;$('#catalogSelectAll').indeterminate=!all&&rows.some(item=>state.selectedCatalogIds.has(String(item.pipeline_id)))}
function renderCatalog(){const summary=state.productCatalog.summary||{};$('#catalogMetrics').innerHTML=[['全部商品',summary.total||0,`${summary.sku_count||0} 个 SKU`],['已上架',summary.published||0,'Ozon 已验证'],['待上架',summary.ready||0,'Payload 已就绪'],['需要处理',(summary.failed||0)+(summary.needs_update||0),`${summary.failed||0} 失败 · ${summary.needs_update||0} 更新`]].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const rows=filteredCatalog();$('#catalogTable').innerHTML=rows.length?rows.map(item=>`<tr><td><input type="checkbox" data-catalog-select="${escapeHtml(item.pipeline_id)}" ${state.selectedCatalogIds.has(String(item.pipeline_id))?'checked':''} aria-label="选择商品 ${escapeHtml(item.pipeline_id)}"></td><td><div class="catalog-product"><div class="catalog-thumb">${item.thumbnail_url?`<img src="${escapeHtml(item.thumbnail_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span>无图</span>'}</div><div><b title="${escapeHtml(item.display_title)}">${escapeHtml(item.display_title)}</b><small>1688 · ${escapeHtml(item.pipeline_id)}${item.title_zh&&item.title_ru?` · ${escapeHtml(item.title_zh)}`:''}</small></div></div></td><td><span class="catalog-status ${escapeHtml(item.status)}">${escapeHtml(catalogStatusName(item.status))}</span>${item.latest_failure?`<small class="catalog-error" title="${escapeHtml(item.latest_failure)}">${escapeHtml(item.latest_failure)}</small>`:''}</td><td>${escapeHtml(item.sku_count)}</td><td>${escapeHtml(item.ozon_category_id||'—')} / ${escapeHtml(item.ozon_type_id||'—')}</td><td>${escapeHtml(catalogPrice(item))}</td><td>${escapeHtml(item.store_id||'—')}</td><td><div class="mini-progress"><i class="progress-${escapeHtml(item.stage_passed_count)}"></i></div><small>${escapeHtml(item.stage_passed_count)}/5</small></td><td>${escapeHtml(formatDate(item.updated_at))}</td><td><button type="button" data-catalog-pipeline="${escapeHtml(item.pipeline_id)}">打开</button></td></tr>`).join(''):'<tr><td colspan="10" class="table-empty">没有符合条件的商品</td></tr>';document.querySelectorAll('[data-catalog-pipeline]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.catalogPipeline);showWorkspace('products')});document.querySelectorAll('[data-catalog-select]').forEach(control=>control.onchange=()=>{const id=String(control.dataset.catalogSelect);if(control.checked)state.selectedCatalogIds.add(id);else state.selectedCatalogIds.delete(id);updateCatalogSelection()});updateCatalogSelection()}
async function loadCatalog(){try{state.productCatalog=await api('/api/products');const valid=new Set((state.productCatalog.products||[]).map(item=>String(item.pipeline_id)));state.selectedCatalogIds=new Set([...state.selectedCatalogIds].filter(id=>valid.has(id)));renderCatalog()}catch(error){toast(error.message,true)}}
function supplierStatusName(value){return{QUEUED:'排队中',RUNNING:'检测中',COMPLETED:'已完成',PARTIAL:'部分失败',INTERRUPTED:'已中断',UNKNOWN:'未知',BASELINE:'已建立基线',UNCHANGED:'无变化',CHANGED:'发现变化',CHECK_FAILED:'检测失败',SCHEDULED:'已计划',DISABLED:'已停用',STARTING:'正在启动',FAILED:'失败',DEFERRED_AFTER_RESTART:'重启后已顺延'}[value]||value||'未检测'}
function renderSupplierMonitor(){const summary=state.supplierMonitor.summary||{};$('#supplierMonitorMetrics').innerHTML=[['已监控',summary.monitored||0,'商品'],['发生变化',summary.changed||0,'待人工确认'],['已断货',summary.out_of_stock||0,'全部 SKU 为零'],['检测失败',summary.failed||0,'接口或数据错误']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const rows=state.supplierMonitor.products||[];$('#supplierMonitorResults').innerHTML=rows.length?rows.map(item=>{const snapshot=item.snapshot||{};const details=(item.changes||[]).map(change=>change.message).join('；')||item.error||`SKU ${snapshot.sku_count||0} · ${snapshot.stock_status==='OUT_OF_STOCK'?'已断货':snapshot.stock_status==='IN_STOCK'?'有库存':'库存未知'}`;return`<article class="version-item"><div><b>${escapeHtml(item.pipeline_id)} · ${escapeHtml(supplierStatusName(item.check_status))}</b><small>${escapeHtml(details)} · ${escapeHtml(formatDate(item.checked_at))}</small></div></article>`}).join(''):'<div class="store-empty">尚未建立供应商监控基线。</div>'}
function renderSupplierSchedule(schedule){$('#supplierScheduleEnabled').checked=Boolean(schedule.enabled);$('#supplierScheduleInterval').value=String(schedule.interval_hours||24);$('#supplierScheduleProducts').value=(schedule.pipeline_ids||[]).join('\n');$('#supplierScheduleConfirm').checked=false;$('#supplierScheduleStatus').textContent=schedule.enabled?'已启用':'未启用';const latest=schedule.last_job_status?` · 最近任务：${supplierStatusName(schedule.last_job_status)}${schedule.last_job_message?`（${schedule.last_job_message}）`:''}`:'';$('#supplierScheduleInfo').textContent=schedule.enabled?`下次检测：${formatDate(schedule.next_run_at)} · 调度状态：${supplierStatusName(schedule.last_status)}${latest}${schedule.last_error?` · ${schedule.last_error}`:''}`:'定时计划未启用；保存禁用状态不会产生接口调用。'}
async function openSupplierMonitor(){if(!state.selectedCatalogIds.size){toast('请先选择商品',true);return}try{state.supplierMonitor=await api('/api/supplier-monitor');renderSupplierMonitor();$('#supplierMonitorConfirm').checked=false;const canSchedule=hasPermission('team.manage');$('#supplierSchedulePanel').classList.toggle('hidden',!canSchedule);if(canSchedule)renderSupplierSchedule((await api('/api/supplier-monitor/schedule')).schedule||{});$('#supplierMonitorDialog').showModal()}catch(error){toast(error.message,true)}}
function stopSupplierMonitorPolling(){if(state.supplierMonitorTimer){clearTimeout(state.supplierMonitorTimer);state.supplierMonitorTimer=null}}
function renderSupplierMonitorJob(job){const total=Number(job.total||0);const completed=Number(job.completed_count||0);const percent=total?Math.round(completed/total*100):0;$('#supplierMonitorResults').innerHTML=`<div class="batch-import-progress"><div><b>${escapeHtml(job.message||'正在检测')}</b><span>${completed}/${total} · ${percent}%</span></div><div class="batch-progress-track"><i style="width:${percent}%"></i></div></div>`+(job.items||[]).map(item=>`<article class="version-item"><div><b>${escapeHtml(item.pipeline_id)} · ${escapeHtml(supplierStatusName(item.status))}</b><small>${escapeHtml((item.changes||[]).map(change=>change.message).join('；')||item.error||'等待检测')}</small></div></article>`).join('')}
async function pollSupplierMonitor(jobId){stopSupplierMonitorPolling();try{const job=await api(`/api/supplier-monitor/jobs/${encodeURIComponent(jobId)}`);state.supplierMonitorJob=job;renderSupplierMonitorJob(job);if(!['COMPLETED','PARTIAL','FAILED','INTERRUPTED'].includes(job.status)){state.supplierMonitorTimer=setTimeout(()=>pollSupplierMonitor(jobId),2000);return}state.supplierMonitor=await api('/api/supplier-monitor');renderSupplierMonitor();$('#runSupplierMonitorBtn').disabled=false;$('#runSupplierMonitorBtn').textContent='检测选中商品';toast(job.message,job.status!=='COMPLETED')}catch(error){$('#runSupplierMonitorBtn').disabled=false;$('#runSupplierMonitorBtn').textContent='检测选中商品';toast(error.message,true)}}
async function runSupplierMonitor(){if(!$('#supplierMonitorConfirm').checked){toast('请先确认允许调用 AlphaShop API',true);return}const ids=[...state.selectedCatalogIds];if(ids.length>20){toast('单次最多检测 20 个商品',true);return}const button=$('#runSupplierMonitorBtn');button.disabled=true;button.textContent='正在创建任务…';try{state.supplierMonitorJob=await api('/api/supplier-monitor',{method:'POST',body:JSON.stringify({pipeline_ids:ids,confirm_external_requests:true})});renderSupplierMonitorJob(state.supplierMonitorJob);toast('供应商检测已进入后台队列');pollSupplierMonitor(state.supplierMonitorJob.job_id)}catch(error){button.disabled=false;button.textContent='检测选中商品';toast(error.message,true)}}
function supplierScheduleIds(){return $('#supplierScheduleProducts').value.split(/[\s,;]+/).map(value=>value.trim()).filter(Boolean)}
async function saveSupplierSchedule(){const enabled=$('#supplierScheduleEnabled').checked;if(enabled&&!$('#supplierScheduleConfirm').checked){toast('请确认周期性 AlphaShop 接口费用',true);return}try{const result=await api('/api/supplier-monitor/schedule',{method:'POST',body:JSON.stringify({enabled,interval_hours:Number($('#supplierScheduleInterval').value),pipeline_ids:supplierScheduleIds(),confirm_recurring_charges:$('#supplierScheduleConfirm').checked})});renderSupplierSchedule(result.schedule||{});toast(enabled?'定时检测计划已启用':'定时检测计划已暂停')}catch(error){toast(error.message,true)}}
async function deleteSupplierSchedule(){if(!confirm('确认删除定时供应商检测计划？已有监控历史不会删除。'))return;try{await api('/api/supplier-monitor/schedule',{method:'DELETE'});renderSupplierSchedule({enabled:false,pipeline_ids:[],interval_hours:24});toast('定时检测计划已删除')}catch(error){toast(error.message,true)}}
const baseRenderCatalogWithVersions=renderCatalog;
renderCatalog=function(){baseRenderCatalogWithVersions();document.querySelectorAll('[data-catalog-pipeline]').forEach(button=>{const pipelineId=button.dataset.catalogPipeline;const row=button.closest('td');if(!row||row.querySelector('[data-product-versions]'))return;const item=(state.productCatalog.products||[]).find(product=>String(product.pipeline_id)===String(pipelineId));const versionButton=document.createElement('button');versionButton.type='button';versionButton.dataset.productVersions=pipelineId;versionButton.textContent=`版本 ${Number(item?.product_version_count||0)}`;versionButton.onclick=()=>openProductVersions(pipelineId);row.classList.add('catalog-row-actions');row.appendChild(versionButton)})};
function openBatchEdit(){if(!state.selectedCatalogIds.size){toast('请先选择至少一个商品',true);return}$('#batchEditStore').innerHTML=storeOptions();$('#batchEditNote').textContent=`已选择 ${state.selectedCatalogIds.size} 个商品。仅修改明确勾选的字段；不会自动组装或上架。`;['#applyBatchStore','#applyBatchRate','#applyBatchDims','#applyBatchVat'].forEach(selector=>$(selector).checked=false);$('#batchEditResults').innerHTML='';$('#submitBatchEditBtn').disabled=false;$('#batchEditDialog').showModal()}
async function saveBatchEdit(event){event.preventDefault();try{const patch={};if($('#applyBatchStore').checked)patch.store_id=$('#batchEditStore').value;if($('#applyBatchRate').checked)patch.cny_to_rub_rate=$('#batchEditRate').value.trim();if($('#applyBatchVat').checked)patch.vat=$('#batchEditVat').value;if($('#applyBatchDims').checked){const dims=$('#batchEditDims').value.split('/').map(value=>Number(value.trim()));if(dims.length!==4||dims.some(value=>!Number.isInteger(value)||value<=0))throw new Error('默认尺寸必须是四个正整数');patch.dimension_defaults={depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'}}if(!Object.keys(patch).length)throw new Error('请至少勾选一个要修改的字段');$('#submitBatchEditBtn').disabled=true;const result=await api('/api/products/batch-edit',{method:'POST',body:JSON.stringify({pipeline_ids:[...state.selectedCatalogIds],patch,note:$('#batchEditDescription').value.trim()})});$('#batchEditResults').innerHTML=(result.results||[]).map(item=>`<div class="batch-result ${item.status==='FAIL'?'fail':'pass'}"><i></i><span><b>${escapeHtml(item.pipeline_id)} · ${escapeHtml(item.status==='UPDATED'?'已保存新版本':item.status==='UNCHANGED'?'没有变化':'失败')}</b><small>${escapeHtml(item.error||item.version_id||'')}</small></span></div>`).join('');state.selectedCatalogIds.clear();await load();await loadCatalog();toast(`批量编辑完成：更新 ${result.updated}，未变化 ${result.unchanged}，失败 ${result.failed}`,result.failed>0)}catch(error){toast(error.message,true)}finally{$('#submitBatchEditBtn').disabled=false}}
function settingsSummary(settings){const dims=settings?.dimension_defaults||{};const size=[dims.depth,dims.width,dims.height,dims.weight].every(value=>value!==null&&value!==undefined)?`${dims.depth}/${dims.width}/${dims.height}/${dims.weight}${dims.weight_unit||'g'}`:'未设置';const vat=Number(settings?.vat||0)*100;return`店铺 ${settings?.store_id||'未设置'} · 汇率 ${settings?.cny_to_rub_rate||'未设置'} · 尺寸重量 ${size} · VAT ${vat}%`}
async function openProductVersions(pipelineId){try{state.versionPipelineId=pipelineId;const history=await api(`/api/pipelines/${encodeURIComponent(pipelineId)}/versions`);$('#productVersionsTitle').textContent=`商品 ${pipelineId} · 版本历史`;const versions=history.versions||[];$('#productVersionsList').innerHTML=versions.length?versions.map((item,index)=>`<article class="version-item"><div><b>${index===0?'当前/最新 · ':''}${escapeHtml(item.note||item.source)}</b><small>${escapeHtml(formatDate(item.created_at))} · ${escapeHtml(item.actor||'system')} · ${escapeHtml(settingsSummary(item.settings))}</small></div><button type="button" data-restore-version="${escapeHtml(item.version_id)}" ${index===0?'disabled':''}>回滚到此版本</button></article>`).join(''):'<div class="store-empty">尚无版本记录。首次批量编辑后会保留初始版本和新版本。</div>';document.querySelectorAll('[data-restore-version]').forEach(button=>button.onclick=()=>restoreProductVersion(button.dataset.restoreVersion));$('#productVersionsDialog').showModal()}catch(error){toast(error.message,true)}}
async function restoreProductVersion(versionId){if(!confirm('确认回滚到该版本？第四、第五阶段将标记为需要更新，但不会自动提交。'))return;try{await api(`/api/pipelines/${encodeURIComponent(state.versionPipelineId)}/versions/${encodeURIComponent(versionId)}/restore`,{method:'POST',body:'{}'});await load();await loadCatalog();await openProductVersions(state.versionPipelineId);toast('版本已回滚，请重新运行第四阶段生成 Payload')}catch(error){toast(error.message,true)}}
function formatBytes(value){const bytes=Number(value||0);if(bytes<1024)return`${bytes} B`;if(bytes<1024*1024)return`${(bytes/1024).toFixed(1)} KB`;if(bytes<1024*1024*1024)return`${(bytes/1024/1024).toFixed(1)} MB`;return`${(bytes/1024/1024/1024).toFixed(2)} GB`}
function assetTypeName(value){return{translated:'俄语翻译图',ai_generated:'AI 优化图'}[value]||value||'图片'}
function filteredAssets(){const query=state.assetSearch.toLowerCase();return(state.assetLibrary.assets||[]).filter(item=>{if(state.assetTypeFilter!=='all'&&item.asset_type!==state.assetTypeFilter)return false;if(state.assetStatusFilter==='managed'&&!item.managed)return false;if(state.assetStatusFilter==='external'&&item.managed)return false;if(state.assetStatusFilter==='orphaned'&&!item.orphaned)return false;if(state.assetStatusFilter==='published'&&!item.published)return false;if(!query)return true;return`${item.display_name||''} ${JSON.stringify(item.references||[])}`.toLowerCase().includes(query)})}
function renderAssets(){const summary=state.assetLibrary.summary||{};$('#assetMetrics').innerHTML=[['已处理图片',summary.total||0,'仅 AI 优化与俄语翻译'],['OSS 托管',summary.managed||0,formatBytes(summary.managed_bytes)],['可安全清理',summary.orphaned||0,formatBytes(summary.orphaned_bytes)],['已上架保护',summary.published||0,'永不自动删除']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const rows=filteredAssets();$('#assetEmpty').classList.toggle('hidden',rows.length>0);$('#assetGrid').innerHTML=rows.map(item=>{const refs=item.references||[];const badges=[`<span class="asset-badge managed">${escapeHtml(assetTypeName(item.asset_type))}</span>`,item.managed?'<span class="asset-badge external">OSS</span>':'<span class="asset-badge external">外部链接</span>',item.orphaned?'<span class="asset-badge orphaned">可清理</span>':'',item.published?'<span class="asset-badge protected">已上架保护</span>':''].join('');const refButtons=refs.slice(0,3).map(ref=>`<button type="button" data-asset-pipeline="${escapeHtml(ref.pipeline_id)}">打开商品${ref.sku_id?` · SKU ${escapeHtml(ref.sku_id)}`:''}</button>`).join('');return`<article class="asset-card asset-link-card"><div class="asset-link-icon">↗</div><div class="asset-body"><div class="asset-badges">${badges}</div><a class="asset-file-link" href="/api/assets/${encodeURIComponent(item.asset_id)}/preview" target="_blank" rel="noopener noreferrer">${escapeHtml(item.display_name||assetTypeName(item.asset_type))}</a><div class="asset-meta"><span>${item.size_bytes?formatBytes(item.size_bytes):'链接图片'}</span><span>${refs.length} 个商品引用</span></div><div class="asset-refs">${refButtons||'<span>当前无商品引用</span>'}${refs.length>3?`<span>+${refs.length-3}</span>`:''}</div>${item.can_delete&&hasPermission('storage.manage')?`<button type="button" class="asset-delete" data-delete-asset="${escapeHtml(item.asset_id)}">从 OSS 永久删除</button>`:''}</div></article>`}).join('');document.querySelectorAll('[data-asset-pipeline]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.assetPipeline);showWorkspace('products')});document.querySelectorAll('[data-delete-asset]').forEach(button=>button.onclick=()=>deleteAsset(button.dataset.deleteAsset))}
async function loadAssets(){try{state.assetLibrary=await api('/api/assets');renderAssets()}catch(error){toast(error.message,true)}}
async function deleteAsset(identifier){if(!confirm('确认从 OSS 永久删除该无引用图片？此操作无法恢复。'))return;try{state.assetLibrary=await api(`/api/assets/${encodeURIComponent(identifier)}`,{method:'DELETE'});renderAssets();toast('无引用图片已从 OSS 删除')}catch(error){toast(error.message,true)}}
async function loadNotifications(showError=true){try{state.notifications=await api('/api/notifications');renderNotifications()}catch(error){if(showError)toast(error.message,true)}}
async function markNotificationsRead(){try{state.notifications=await api('/api/notifications/read',{method:'POST',body:JSON.stringify({all:true})});renderNotifications();toast('通知已全部标记为已读')}catch(error){toast(error.message,true)}}
function showWorkspace(view){const operations=view==='operations';const pricing=view==='pricing';const tasks=view==='tasks';const catalog=view==='catalog';const research=view==='research';const assets=view==='assets';$('#productShell').classList.toggle('hidden',operations||pricing||tasks||catalog||research||assets);$('#operationsView').classList.toggle('hidden',!operations);$('#pricingView').classList.toggle('hidden',!pricing);$('#taskView').classList.toggle('hidden',!tasks);$('#catalogView').classList.toggle('hidden',!catalog);$('#researchView').classList.toggle('hidden',!research);$('#assetView').classList.toggle('hidden',!assets);$('#productNav').classList.toggle('active',view==='products');$('#catalogNav').classList.toggle('active',catalog);$('#researchNav').classList.toggle('active',research);$('#taskNav').classList.toggle('active',tasks);$('#assetNav').classList.toggle('active',assets);$('#operationsNav').classList.toggle('active',operations);$('#pricingNav').classList.toggle('active',pricing);if(operations){$('#operationsStore').innerHTML=operationsStoreOptions();$('#refreshOperationsBtn').disabled=!state.stores.length;$('#financeSettingsBtn').disabled=!state.stores.length||!hasPermission('finance.read');if(!state.stores.length)$('#operationsEmpty').textContent='请先回到商品工作台授权 Ozon 店铺。'}if(pricing){$('#pricingStore').innerHTML=operationsStoreOptions();$('#loadPricingSettingsBtn').disabled=!state.stores.length||!hasPermission('finance.read')}if(tasks)loadTaskCenter();if(catalog)loadCatalog();if(research)loadResearch();if(assets)loadAssets()}
function renderAccount(){if(!state.account)return;const account=state.account;const name=account.identity.display_name||account.identity.username;const initial=name.slice(0,1).toUpperCase();$('#accountAvatar').textContent=initial;$('#accountDialogAvatar').textContent=initial;$('#accountName').textContent=name;$('#accountDialogName').textContent=name;$('#accountPlan').textContent=account.plan.name;$('#accountRole').textContent=`${account.identity.role_name} · ${account.workspace.name}`;$('#planName').textContent=account.plan.name;$('#planPrice').textContent=`¥${Number(account.plan.monthly_price_cny).toLocaleString('zh-CN')} / 月`;$('#billingPeriod').textContent=`计费周期 ${account.period}`;$('#usageGrid').innerHTML=Object.entries(account.plan.limits).map(([key,limit])=>{const used=Number(account.usage[key]||0);const percent=Math.min(100,Math.round(used/Math.max(1,Number(limit))*100));return `<article><div><span>${usageLabel(key)}</span><b>${used} / ${limit}</b></div><progress class="usage-track" max="100" value="${percent}" aria-label="${escapeHtml(usageLabel(key))}用量 ${percent}%"></progress><small>${percent}% 已使用</small></article>`}).join('');$('#permissionList').innerHTML=(account.identity.permission_labels||[]).map(item=>`<span>✓ ${escapeHtml(item)}</span>`).join('');$('#createForm').querySelector('button[type="submit"]').disabled=!hasPermission('pipeline.create');$('#storesBtn').disabled=!hasPermission('stores.manage');$('#aiProviderBtn').disabled=!hasPermission('ai.manage');renderTeam()}
async function load(){try{const [list,config,stores,provider,dashboard,account,team]=await Promise.all([api('/api/pipelines'),api('/api/config-status'),api('/api/stores'),api('/api/ai-provider'),api('/api/dashboard'),api('/api/account'),api('/api/team')]);state.pipelines=list.pipelines;state.config=config;state.stores=stores.stores;state.aiProvider=provider.provider;state.dashboard=dashboard;state.account=account;state.team=team;$('#modeBadge').textContent=config.dry_run?'DRY RUN':'LIVE MODE';$('#modeBadge').className=`badge ${config.dry_run?'safe':'live'}`;$('#aiProviderState').textContent=state.aiProvider.text_api_key_configured&&state.aiProvider.image_api_key_configured?'✓':'0';$('#operationsStore').innerHTML=operationsStoreOptions();$('#pricingStore').innerHTML=operationsStoreOptions();if(state.current){const found=state.pipelines.find(p=>p.pipeline_id===state.current.pipeline_id);if(found)state.current=await api(`/api/pipelines/${encodeURIComponent(found.pipeline_id)}`)}renderAccount();$('#pricingNav').disabled=!hasPermission('finance.read');renderStores();renderList();renderDetail()}catch(error){toast(error.message,true)}}
async function saveTeamMember(event){event.preventDefault();try{await api('/api/team',{method:'POST',body:JSON.stringify({username:$('#memberUsername').value.trim(),display_name:$('#memberDisplayName').value.trim(),role:$('#memberRole').value})});$('#memberUsername').value='';$('#memberDisplayName').value='';await load();toast('团队成员已保存，请在服务器创建同名登录凭证')}catch(error){toast(error.message,true)}}
async function deleteTeamMember(username){if(!confirm(`确认移除团队成员 ${username}？`))return;try{await api(`/api/team/${encodeURIComponent(username)}`,{method:'DELETE'});await load();toast('团队成员已移除')}catch(error){toast(error.message,true)}}
async function selectPipeline(id){try{state.current=await api(`/api/pipelines/${encodeURIComponent(id)}`);renderList();renderDetail()}catch(error){toast(error.message,true)}}
async function viewArtifact(n){try{const value=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/artifacts/${n}`);const failures=state.current?.stages?.[String(n)]?.failures||[];$('#artifactTitle').textContent=`0${n} · ${state.current.artifacts[String(n)]}`;$('#console').textContent=`${failures.length?`门禁失败：\n- ${failures.join('\n- ')}\n\n`:''}${JSON.stringify(value,null,2)}`}catch(error){toast(error.message,true)}}
function field(label,name,value=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" value="${escapeHtml(value)}"></div>`}
function storeField(){return `<div class="field"><label for="stageStore">OZON 店铺</label><select id="stageStore" required>${storeOptions()}</select></div>`}
function categoryOptionLabel(option){const zhPath=(option.category_path_zh||[]).join(' / ');const zhType=option.type_name_zh||'';const ruPath=(option.category_path_ru||[]).join(' / ');const ruType=option.type_name_ru||'';return `${zhPath}${zhType?` · ${zhType}`:''}${ruPath?` ｜ ${ruPath}`:''}${ruType?` · ${ruType}`:''} ｜ category ${option.ozon_category_id} / type ${option.ozon_type_id}`}
async function searchOzonCategories(){const query=$('#categoryQuery').value.trim();if(query.length<2){toast('请输入至少 2 个类目关键词，例如“香薰石牌”',true);return}const button=$('#searchCategoryBtn');const select=$('#manualCategory');button.disabled=true;button.textContent='正在读取 Ozon…';select.innerHTML='<option value="">正在搜索官方类目树…</option>';try{const storeId=$('#stageStore').value;const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/category-options?q=${encodeURIComponent(query)}&store_id=${encodeURIComponent(storeId)}`);const options=result.options||[];select.innerHTML='<option value="">请选择正确的 Ozon 官方类目 / 商品类型</option>'+options.map(option=>`<option value="${option.ozon_category_id}:${option.ozon_type_id}">${escapeHtml(categoryOptionLabel(option))}</option>`).join('');$('#categorySearchStatus').textContent=options.length?`找到 ${result.total_matches} 个匹配项，按相关度显示前 ${options.length} 个。请核对“商品类型”，不要选择香薰蜡烛。`:'没有匹配项，请尝试“香薰石”“扩香石”“香薰挂件”或俄语关键词。'}catch(error){select.innerHTML='<option value="">读取失败，请重试</option>';$('#categorySearchStatus').textContent=error.message;toast(error.message,true)}finally{button.disabled=false;button.textContent='搜索 Ozon 官方类目'}}
function attributeTextValue(value){if(Array.isArray(value))return value.join(', ');if(value&&typeof value==='object')return JSON.stringify(value);return String(value??'')}
function requiredAttributeFields(attributes){if(!attributes.length)return '<div class="warning">Ozon 当前类目没有可编辑特征。</div>';return `<div class="warning">以下是当前类目的全部 Ozon 特征（包含选填项）。字段名和字典候选值使用 Ozon 官方简体中文显示；系统内部保留同一个属性 ID，组装上架载荷时自动换成 Ozon 俄语合法值。自由文本可直接输入中文，保存第四阶段时会调用已配置的 AI 文本服务一次性译为俄语。</div>${attributes.map(attribute=>{const id=attribute.attribute_id;const required=attribute.is_required;const zhName=attribute.attribute_name_zh||`Ozon 特征 ${id}`;const ruName=attribute.attribute_name_ru||'';const label=`${required?'【必填】':'【可选】'} ${zhName} · ID ${id}`;const ruHint=ruName&&ruName!==zhName?`Ozon 俄语字段：${escapeHtml(ruName)}`:'';if(attribute.is_dictionary){const selectedId=attribute.selected_dictionary_value_id??'';const current=selectedId!==''?`<option value="${selectedId}" selected>已选择 · ID ${selectedId}</option>`:'';return `<div class="field"><label for="attribute_${id}">${escapeHtml(label)}</label><select id="attribute_${id}" data-required-attribute="${id}" data-attribute-kind="dictionary" data-is-required="${required}" data-original="${selectedId}" data-override-required="${attribute.override_required}" data-values-loaded="false"><option value="">${required?'请选择 Ozon 合法值':'留空，不提交此可选特征'}</option>${current}</select><small>${ruHint}${ruHint?' · ':''}展开时从 Ozon API 实时加载中文候选值</small></div>`}const textValue=attributeTextValue(attribute.selected_value);return `<div class="field"><label for="attribute_${id}">${escapeHtml(label)}</label><input id="attribute_${id}" data-required-attribute="${id}" data-attribute-kind="text" data-is-required="${required}" data-original="${escapeHtml(textValue)}" data-override-required="${attribute.override_required}" value="${escapeHtml(textValue)}" placeholder="${required?'请输入准确的中文特征值':'可选，可输入中文，留空则不提交'}"><small>${ruHint}${ruHint?' · ':''}新输入的中文会在载荷组装前译为俄语；已有俄语值保持不变</small></div>`}).join('')}`}
async function loadAttributeDictionary(control){if(control.dataset.valuesLoaded==='true')return;control.dataset.valuesLoaded='loading';const current=control.value;const empty=control.options[0]?.textContent||'留空';try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/attributes/${encodeURIComponent(control.dataset.requiredAttribute)}/values`);control.innerHTML=`<option value="">${escapeHtml(empty)}</option>`+(result.options||[]).map(option=>`<option value="${option.dictionary_value_id}" ${String(option.dictionary_value_id)===current?'selected':''}>${escapeHtml(option.value)} · ${option.dictionary_value_id}</option>`).join('');control.dataset.valuesLoaded='true'}catch(error){control.dataset.valuesLoaded='false';toast(error.message,true)}}
async function openStage(n){state.dialogStage=n;const titles=['','采集 1688 商品','匹配 OZON 类目','生成俄语内容','组装上传 Payload','提交与追踪'];$('#dialogTitle').textContent=titles[n];let html='';if(n===1)html='<div class="warning">重新采集会调用 AlphaShop 实时详情接口，并使后续产物需要重新验证。</div>';if(n===2)html=storeField()+field('自动选择置信度阈值','threshold','0.70');if(n===3){const aiReady=state.aiProvider?.text_api_key_configured&&state.aiProvider?.image_api_key_configured;html=`<div class="warning">请先在阶段 1 的“图片”中设置每张图的用途。共用八图会调用生图模型 8 次；SKU 主图每张调用 1 次；翻译图只进入 Rich Content。</div><div class="field"><label for="mediaMode">图片处理方式</label><select id="mediaMode"><option value="image_plan" ${aiReady?'selected':''} ${aiReady?'':'disabled'}>执行逐图处理方案（推荐）</option><option value="alphashop_translate">全部使用 AlphaShop 翻译</option><option value="ai_generate" ${state.aiProvider?.image_api_key_configured?'':'disabled'}>全部逐张 AI 生图（旧模式）</option></select></div><div class="field"><label for="textMode">俄语文本方式</label><select id="textMode"><option value="built_in">内置严格规则</option><option value="ai_generate" ${aiReady?'selected':''} ${state.aiProvider?.text_api_key_configured?'':'disabled'}>AI 生成标题、描述和标签</option></select></div>${aiReady?'':`<div class="warning danger">AI 服务尚未配置完整，请先点击页面顶部“AI 服务”。</div>`}`};if(n===4){html=storeField()+field('CNY → 店铺币种汇率','rate','12.50')+field('估算尺寸：深 / 宽 / 高 / 重量(g)','dims','80 / 80 / 200 / 350')+'<div id="requiredAttributes"><div class="warning">正在读取当前类目的全部 Ozon 特征…</div></div>'}if(n===5){const blocked=state.config?.dry_run;html=`<div class="warning danger">${blocked?'服务器当前为 DRY RUN，真实提交已锁定；本次运行绝不会被标记为上架成功。请先在服务器启用 LIVE MODE。':'服务器已处于 LIVE MODE。勾选确认后才会调用 Ozon，并且只有取得 task_id、导入成功且属性回查通过才会显示 PASS。'}</div><div class="field"><label><input id="execute" type="checkbox" ${blocked?'disabled':''}> 我明确要求执行真实提交</label></div>`}$('#dialogFields').innerHTML=html;$('#stageDialog').showModal();if(n===4){try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/required-attributes`);$('#requiredAttributes').innerHTML=requiredAttributeFields(result.attributes||[]);document.querySelectorAll('[data-attribute-kind="dictionary"]').forEach(control=>control.onfocus=()=>loadAttributeDictionary(control))}catch(error){$('#requiredAttributes').innerHTML=`<div class="warning danger">${escapeHtml(error.message)}</div>`;toast(error.message,true)}}}
const delay=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
async function waitForStage(n){for(let attempt=0;attempt<1200;attempt++){await delay(3000);state.current=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}`);renderList();renderDetail();const status=stageStatus(state.current,n);$('#console').textContent=`阶段 ${n} 正在后台执行… 已等待 ${Math.round((attempt+1)*3)} 秒`;if(status!=='RUNNING')return status}throw new Error(`阶段 ${n} 后台执行超过 60 分钟，请检查服务日志`)}
async function runStage(event){event.preventDefault();const n=state.dialogStage;let body={};try{if(n===2){body.confidence_threshold=Number($('#threshold').value);body.store_id=$('#stageStore').value}if(n===3){body.media_mode=$('#mediaMode').value;body.text_mode=$('#textMode').value}if(n===4){const dims=$('#dims').value.split('/').map(v=>Number(v.trim()));if(dims.length!==4||dims.some(v=>!Number.isFinite(v)||v<=0))throw new Error('尺寸必须是四个正数');const attributeOverrides={};document.querySelectorAll('[data-required-attribute]').forEach(control=>{const value=control.value.trim();if(!value&&control.dataset.isRequired==='true')throw new Error(`请填写或选择 ${control.previousElementSibling?.textContent||'Ozon 必填属性'}`);const changed=value!==String(control.dataset.original??'');if(value&&(changed||control.dataset.overrideRequired==='true'))attributeOverrides[control.dataset.requiredAttribute]=control.dataset.attributeKind==='dictionary'?{dictionary_value_id:Number(value)}:{value}});body.store_config={store_id:$('#stageStore').value,cny_to_rub_rate:$('#rate').value.trim(),dimension_defaults:{depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'},vat:'0',attribute_overrides:attributeOverrides}}if(n===5){if(state.config?.dry_run)throw new Error('服务器仍为 DRY RUN，请先启用 LIVE MODE 并重启服务');if(!$('#execute').checked)throw new Error('请勾选“我明确要求执行真实提交”');body.execute=true}$('#stageDialog').close();$('#console').textContent=`正在执行阶段 ${n}…`;let result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/stages/${n}`,{method:'POST',body:JSON.stringify(body)});if(result.status==='RUNNING'){toast(`阶段 ${n} 已转入后台执行`);await selectPipeline(state.current.pipeline_id);await waitForStage(n);result={...result,status:stageStatus(state.current,n),failures:state.current.stages?.[String(n)]?.failures||[]}}const failures=result.failures||[];const details=failures.join('；');if(failures.length)$('#console').textContent=`门禁失败：\n- ${failures.join('\n- ')}`;toast(`阶段 ${n}：${result.status}${details?` · ${details}`:''}`,result.status==='FAIL');await selectPipeline(state.current.pipeline_id);if(state.current.artifacts?.[String(n)])await viewArtifact(n)}catch(error){toast(error.message,true)}}
const baseOpenStage=openStage;
const baseRunStage=runStage;
async function openStageWithCategoryPicker(n){if(n!==2)return baseOpenStage(n);state.dialogStage=2;$('#dialogTitle').textContent='匹配 OZON 类目';$('#dialogFields').innerHTML=storeField()+`<div class="warning danger">类目决定商品类型和整套 Ozon 特征。请搜索并人工确认官方类目；“香薰石牌”不能继续使用“香薰蜡烛”的类目或类型。</div><div class="field"><label for="categoryQuery">商品类目关键词（中文或俄语）</label><div class="category-search-row"><input id="categoryQuery" value="香薰石牌" placeholder="例如：香薰石牌"><button id="searchCategoryBtn" type="button">搜索 Ozon 官方类目</button></div><small id="categorySearchStatus">搜索结果来自当前授权店铺的 Ozon 实时类目树。</small></div><div class="field"><label for="manualCategory">Ozon 官方类目 / 商品类型</label><select id="manualCategory" required><option value="">请先搜索并选择正确类目</option></select></div>`+field('选择置信度阈值','threshold','0.70');$('#stageDialog').showModal();$('#searchCategoryBtn').onclick=searchOzonCategories;$('#categoryQuery').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();searchOzonCategories()}};await searchOzonCategories()}
async function runStageWithCategoryPicker(event){if(state.dialogStage!==2)return baseRunStage(event);event.preventDefault();try{const pair=$('#manualCategory').value.split(':');if(pair.length!==2)throw new Error('请先搜索并选择正确的 Ozon 官方类目 / 商品类型');const body={confidence_threshold:Number($('#threshold').value),store_id:$('#stageStore').value,manual_category_id:Number(pair[0]),manual_type_id:Number(pair[1])};$('#stageDialog').close();$('#console').textContent='正在按人工选择的 Ozon 官方类目重新映射…';const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/stages/2`,{method:'POST',body:JSON.stringify(body)});const failures=result.failures||[];if(failures.length)$('#console').textContent=`门禁失败：\n- ${failures.join('\n- ')}`;toast(`阶段 2：${result.status}${failures.length?` · ${failures.join('；')}`:''}`,result.status==='FAIL');await selectPipeline(state.current.pipeline_id);if(state.current.artifacts?.['2'])await viewArtifact(2)}catch(error){toast(error.message,true)}}
openStage=openStageWithCategoryPicker;
runStage=runStageWithCategoryPicker;
const baseOpenStageWithCategoryPicker=openStage;
const baseRunStageWithCategoryPicker=runStage;
function skuPriceEditor(source){const rows=(source.sku_list||[]).filter(item=>item&&item.sku_id!=null);if(!rows.length)return '<div class="warning danger">采集结果没有可定价的 SKU，请重新运行第一阶段。</div>';return `<div class="warning">这里填写的是人民币真实采购成本，不是上架售价。第四阶段会读取店铺定价参数，按 OGL/邮政运费、全部费率和目标利润自动生成每个 SKU 的上架价；系统绝不会用 0 元上架。</div>${rows.map(item=>{const id=String(item.sku_id);const specs=item.specification_text_zh||((item.specification_zh||[]).map(part=>`${part.name||''}:${part.value||''}`).join('；'))||'默认规格';const price=item.purchase_price_cny??'';return `<div class="field"><label for="sku_price_${escapeHtml(id)}">SKU ${escapeHtml(id)} · ${escapeHtml(specs)} · 人民币采购成本</label><input id="sku_price_${escapeHtml(id)}" type="number" min="0.01" step="0.01" data-sku-price="${escapeHtml(id)}" value="${escapeHtml(price)}" placeholder="请输入真实采购成本，例如 12.80"></div>`}).join('')}`}
async function openStageWithPriceEditor(n){await baseOpenStageWithCategoryPicker(n);if(n!==4)return;try{const selected=state.stores.find(store=>store.store_id===$('#stageStore').value);if(selected?.currency_code==='CNY'){$('#rate').value='1.00';$('#rate').readOnly=true;$('#rate').previousElementSibling.textContent='CNY 店铺：建议售价直接以人民币提交'}else if(selected&&hasPermission('finance.read')){const settings=(await api(`/api/finance-settings?store_id=${encodeURIComponent(selected.store_id)}`)).settings;$('#rate').value=settings.cny_to_rub_rate}const source=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/artifacts/1`);const target=$('#requiredAttributes');target.insertAdjacentHTML('beforebegin',`<div id="skuPriceEditor">${skuPriceEditor(source)}</div>`)}catch(error){toast(`读取 SKU 采购价或定价参数失败：${error.message}`,true)}}
async function runStageWithPriceEditor(event){if(state.dialogStage!==4)return baseRunStageWithCategoryPicker(event);event.preventDefault();try{const dims=$('#dims').value.split('/').map(value=>Number(value.trim()));if(dims.length!==4||dims.some(value=>!Number.isFinite(value)||value<=0))throw new Error('尺寸必须是四个正数');const skuPriceOverrides={};document.querySelectorAll('[data-sku-price]').forEach(control=>{const value=control.value.trim();if(!value)throw new Error(`请填写 SKU ${control.dataset.skuPrice} 的真实人民币采购价`);if(!Number.isFinite(Number(value))||Number(value)<=0)throw new Error(`SKU ${control.dataset.skuPrice} 的采购价必须大于 0`);skuPriceOverrides[control.dataset.skuPrice]=value});const attributeOverrides={};document.querySelectorAll('[data-required-attribute]').forEach(control=>{const value=control.value.trim();if(!value&&control.dataset.isRequired==='true')throw new Error(`请填写或选择 ${control.previousElementSibling?.textContent||'Ozon 必填属性'}`);const changed=value!==String(control.dataset.original??'');if(value&&(changed||control.dataset.overrideRequired==='true'))attributeOverrides[control.dataset.requiredAttribute]=control.dataset.attributeKind==='dictionary'?{dictionary_value_id:Number(value)}:{value}});const body={store_config:{store_id:$('#stageStore').value,cny_to_rub_rate:$('#rate').value.trim(),dimension_defaults:{depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'},vat:$('#stageVat')?.value||'0',sku_price_overrides:skuPriceOverrides,attribute_overrides:attributeOverrides}};$('#stageDialog').close();$('#console').textContent='正在校验采购价并组装 Ozon Payload…';const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/stages/4`,{method:'POST',body:JSON.stringify(body)});const failures=result.failures||[];if(failures.length)$('#console').textContent=`门禁失败：\n- ${failures.join('\n- ')}`;toast(`阶段 4：${result.status}${failures.length?` · ${failures.join('；')}`:''}`,result.status==='FAIL');await selectPipeline(state.current.pipeline_id);if(state.current.artifacts?.['4'])await viewArtifact(4)}catch(error){toast(error.message,true)}}
openStage=openStageWithPriceEditor;
runStage=runStageWithPriceEditor;
const baseOpenStageWithSavedSettings=openStage;
openStage=async function(n){await baseOpenStageWithSavedSettings(n);if(n!==4)return;const settings=state.current?.product_settings||{};const dimensions=settings.dimension_defaults||{};if(settings.store_id&&state.stores.some(store=>store.store_id===settings.store_id))$('#stageStore').value=settings.store_id;if(settings.cny_to_rub_rate)$('#rate').value=settings.cny_to_rub_rate;if([dimensions.depth,dimensions.width,dimensions.height,dimensions.weight].every(value=>value!==null&&value!==undefined))$('#dims').value=`${dimensions.depth} / ${dimensions.width} / ${dimensions.height} / ${dimensions.weight}`;const target=$('#requiredAttributes');if(target&&!$('#stageVat'))target.insertAdjacentHTML('beforebegin',`<div class="field"><label for="stageVat">VAT</label><select id="stageVat"><option value="0">0%</option><option value="0.05">5%</option><option value="0.07">7%</option><option value="0.1">10%</option><option value="0.12">12%</option><option value="0.2">20%</option></select></div>`);if($('#stageVat'))$('#stageVat').value=settings.vat||'0'};
async function authorizeStore(event){event.preventDefault();const payload={store_id:$('#storeId').value.trim(),name:$('#storeName').value.trim(),client_id:$('#ozonClientId').value.trim(),api_key:$('#ozonApiKey').value.trim(),currency_code:$('#ozonCurrency').value};try{toast('正在通过 OZON 只读接口验证凭证…');await api('/api/stores',{method:'POST',body:JSON.stringify(payload)});$('#ozonApiKey').value='';await load();toast('OZON 店铺授权成功')}catch(error){$('#ozonApiKey').value='';toast(error.message,true)}}
async function verifyStore(storeId){try{await api(`/api/stores/${encodeURIComponent(storeId)}/verify`,{method:'POST',body:'{}'});await load();toast('店铺凭证验证通过')}catch(error){toast(error.message,true)}}
async function deleteStore(storeId){if(!confirm(`确认删除店铺授权 ${storeId}？已生成的流水线产物不会删除。`))return;try{await api(`/api/stores/${encodeURIComponent(storeId)}`,{method:'DELETE'});await load();toast('店铺授权已删除')}catch(error){toast(error.message,true)}}
$('#createForm').onsubmit=async event=>{event.preventDefault();const id=$('#offerId').value.trim();try{$('#console').textContent='正在调用 AlphaShop 商品详情 API…';const result=await api('/api/pipelines',{method:'POST',body:JSON.stringify({offer_id:id})});toast(`采集阶段：${result.status}`,result.status==='FAIL');await load();await selectPipeline(result.pipeline_id);await viewArtifact(1)}catch(error){toast(error.message,true)}};
function openAiProvider(){const p=state.aiProvider||{};$('#aiBaseUrl').value=p.base_url||'https://gpt.gptzzz.xyz/v1';$('#aiTextModel').value=p.text_model||'gpt-5.6-sol';$('#aiImageModel').value=p.image_model||'gpt-image-2';$('#aiTextKey').value='';$('#aiImageKey').value='';$('#aiProviderDialog').showModal()}
async function saveAiProvider(event){event.preventDefault();const payload={base_url:$('#aiBaseUrl').value.trim(),text_model:$('#aiTextModel').value.trim(),image_model:$('#aiImageModel').value.trim(),text_api_key:$('#aiTextKey').value.trim(),image_api_key:$('#aiImageKey').value.trim()};try{await api('/api/ai-provider',{method:'POST',body:JSON.stringify(payload)});$('#aiTextKey').value='';$('#aiImageKey').value='';$('#aiProviderDialog').close();await load();toast('AI 服务已安全保存，密钥不会回显')}catch(error){$('#aiTextKey').value='';$('#aiImageKey').value='';toast(error.message,true)}}
async function deleteAiProvider(){if(!confirm('确认删除服务器中的 AI 私有配置？'))return;try{await api('/api/ai-provider',{method:'DELETE'});$('#aiProviderDialog').close();await load();toast('AI 私有配置已删除')}catch(error){toast(error.message,true)}}
function renderObjectStorage(){const storage=state.objectStorage||{};$('#objectStorageState').textContent=storage.configured?'✓':'0';$('#ossEndpoint').value=storage.endpoint||'https://oss-cn-hongkong.aliyuncs.com';$('#ossBucket').value=storage.bucket||'';$('#ossPrefix').value=storage.prefix||'northstar';$('#ossPublicBaseUrl').value=storage.public_base_url||'';$('#ossAccessKeyId').value='';$('#ossAccessKeyId').placeholder=storage.access_key_id_hint?`已配置 ${storage.access_key_id_hint}，留空保持不变`:'请输入 RAM AccessKey ID';$('#ossAccessKeyId').required=!storage.configured;$('#ossAccessKeySecret').value='';$('#ossAccessKeySecret').placeholder=storage.configured?'已配置，留空保持不变':'请输入 RAM AccessKey Secret';$('#ossAccessKeySecret').required=!storage.configured;$('#deleteObjectStorageBtn').disabled=!storage.configured||(state.account&&!hasPermission('storage.manage'))}
async function loadObjectStorage(showError=true){try{state.objectStorage=(await api('/api/object-storage')).storage;renderObjectStorage()}catch(error){if(showError)toast(error.message,true)}}
async function openObjectStorage(){await loadObjectStorage();renderObjectStorage();$('#objectStorageDialog').showModal()}
async function saveObjectStorage(event){event.preventDefault();const payload={endpoint:$('#ossEndpoint').value.trim(),bucket:$('#ossBucket').value.trim(),prefix:$('#ossPrefix').value.trim(),public_base_url:$('#ossPublicBaseUrl').value.trim(),access_key_id:$('#ossAccessKeyId').value.trim(),access_key_secret:$('#ossAccessKeySecret').value.trim()};try{toast('正在向 OSS 上传验证图片…');state.objectStorage=(await api('/api/object-storage',{method:'POST',body:JSON.stringify(payload)})).storage;$('#ossAccessKeyId').value='';$('#ossAccessKeySecret').value='';renderObjectStorage();$('#objectStorageDialog').close();toast('图片存储验证成功，后续图片将自动固化到 OSS')}catch(error){$('#ossAccessKeySecret').value='';toast(error.message,true)}}
async function deleteObjectStorage(){if(!confirm('确认删除图片存储配置？已上传到 OSS 的图片不会删除。'))return;try{await api('/api/object-storage',{method:'DELETE'});state.objectStorage={configured:false};renderObjectStorage();$('#objectStorageDialog').close();toast('图片存储配置已删除')}catch(error){toast(error.message,true)}}
const batchTerminalStatuses=new Set(['COMPLETED','PARTIAL','FAILED','INTERRUPTED']);
function batchStatusName(status){return{QUEUED:'排队中',RUNNING:'采集中',COMPLETED:'全部完成',PARTIAL:'部分成功',FAILED:'全部失败',INTERRUPTED:'已中断',PASS:'成功',FAIL:'失败'}[status]||status}
function renderBatchImport(){const job=state.batchImportJob;const progress=$('#batchImportProgress');const results=$('#batchImportResults');if(!job){progress.classList.add('hidden');results.innerHTML='<div class="store-empty">还没有批量采集记录。</div>';$('#submitBatchImportBtn').disabled=false;return}const total=Number(job.total||0);const completed=Number(job.completed_count||0);const percent=total?Math.round(completed/total*100):0;progress.classList.remove('hidden');progress.innerHTML=`<div><b>${escapeHtml(batchStatusName(job.status))}</b><span>${completed}/${total} · ${percent}%</span></div><div class="batch-progress-track"><i style="width:${Math.min(100,percent)}%"></i></div><small>${escapeHtml(job.message||'')}${job.duplicate_count?` · 已跳过 ${job.duplicate_count} 条重复输入`:''}</small>`;results.innerHTML=(job.items||[]).map(item=>`<button class="batch-result ${String(item.status||'').toLowerCase()}" type="button" ${item.pipeline_id?`data-batch-pipeline="${escapeHtml(item.pipeline_id)}"`:''}><i></i><span><b>${escapeHtml(item.pipeline_id||item.input||'无法识别')}</b><small>${escapeHtml(batchStatusName(item.status))}${item.error?` · ${escapeHtml(item.error)}`:''}</small></span></button>`).join('');document.querySelectorAll('[data-batch-pipeline]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.batchPipeline);$('#batchImportDialog').close();showWorkspace('products')});$('#submitBatchImportBtn').disabled=!batchTerminalStatuses.has(job.status)}
function stopBatchPolling(){if(state.batchImportTimer){clearTimeout(state.batchImportTimer);state.batchImportTimer=null}}
async function pollBatchImport(jobId){stopBatchPolling();try{state.batchImportJob=await api(`/api/batch-imports/${encodeURIComponent(jobId)}`);renderBatchImport();if(!batchTerminalStatuses.has(state.batchImportJob.status)){state.batchImportTimer=setTimeout(()=>pollBatchImport(jobId),2000)}else{await load();toast(state.batchImportJob.message,state.batchImportJob.status!=='COMPLETED')}}catch(error){toast(error.message,true)}}
async function openBatchImport(){try{const latest=(await api('/api/batch-imports?limit=1')).jobs||[];state.batchImportJob=latest[0]||null;renderBatchImport();$('#batchImportDialog').showModal();if(state.batchImportJob&&!batchTerminalStatuses.has(state.batchImportJob.status))pollBatchImport(state.batchImportJob.job_id)}catch(error){toast(error.message,true)}}
function resetBatchImport(){stopBatchPolling();state.batchImportJob=null;$('#batchImportItems').value='';$('#batchImportConfirm').checked=false;renderBatchImport()}
async function startBatchImport(event){event.preventDefault();try{const items=$('#batchImportItems').value.trim();if(!items)throw new Error('请输入至少一个 1688 商品 ID 或链接');if(!$('#batchImportConfirm').checked)throw new Error('请先确认允许调用 AlphaShop API');$('#submitBatchImportBtn').disabled=true;state.batchImportJob=await api('/api/batch-imports',{method:'POST',body:JSON.stringify({items,confirm_external_requests:true})});renderBatchImport();toast('批量采集已转入后台队列');pollBatchImport(state.batchImportJob.job_id)}catch(error){$('#submitBatchImportBtn').disabled=false;toast(error.message,true)}}
function batchProcessStatusName(status){return{QUEUED:'排队中',RUNNING:'处理中',COMPLETED:'全部完成',PARTIAL:'部分成功',FAILED:'全部失败',INTERRUPTED:'已中断',PASS:'成功',FAIL:'失败'}[status]||status}
function updateBatchProcessFields(){const target=Number($('#batchTargetStage').value);$('#batchStage3Fields').classList.toggle('hidden',target<3);$('#batchStage4Fields').classList.toggle('hidden',target<4)}
function renderBatchProcess(){const job=state.batchProcessJob;const progress=$('#batchProcessProgress');const results=$('#batchProcessResults');if(!job){progress.classList.add('hidden');results.innerHTML='<div class="store-empty">选择商品后开始批量处理。</div>';$('#submitBatchProcessBtn').disabled=state.batchProcessHistoryMode;return}const total=Number(job.total||0);const completed=Number(job.completed_count||0);const percent=total?Math.round(completed/total*100):0;progress.classList.remove('hidden');progress.innerHTML=`<div><b>${escapeHtml(batchProcessStatusName(job.status))}</b><span>${completed}/${total} · ${percent}%</span></div><div class="batch-progress-track"><i style="width:${Math.min(100,percent)}%"></i></div><small>${escapeHtml(job.message||'')}</small>`;results.innerHTML=(job.items||[]).map(item=>`<button class="batch-result ${String(item.status||'').toLowerCase()}" type="button" data-process-pipeline="${escapeHtml(item.pipeline_id)}"><i></i><span><b>${escapeHtml(item.pipeline_id)} · ${escapeHtml(batchProcessStatusName(item.status))}</b><small>${item.current_stage?`阶段 ${escapeHtml(item.current_stage)} · `:''}${item.error?escapeHtml(item.error):(item.stage_results||[]).map(row=>`${row.stage}:${row.status}`).join(' · ')}</small></span></button>`).join('');document.querySelectorAll('[data-process-pipeline]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.processPipeline);$('#batchProcessDialog').close();showWorkspace('products')});$('#submitBatchProcessBtn').disabled=state.batchProcessHistoryMode||!batchTerminalStatuses.has(job.status)}
function stopBatchProcessPolling(){if(state.batchProcessTimer){clearTimeout(state.batchProcessTimer);state.batchProcessTimer=null}}
async function pollBatchProcess(jobId){stopBatchProcessPolling();try{state.batchProcessJob=await api(`/api/batch-processes/${encodeURIComponent(jobId)}`);renderBatchProcess();if(!batchTerminalStatuses.has(state.batchProcessJob.status)){state.batchProcessTimer=setTimeout(()=>pollBatchProcess(jobId),2500)}else{state.selectedCatalogIds.clear();await load();await loadCatalog();toast(state.batchProcessJob.message,state.batchProcessJob.status!=='COMPLETED')}}catch(error){toast(error.message,true)}}
async function openBatchProcess(){if(!state.selectedCatalogIds.size){toast('请先选择至少一个商品',true);return}if(!state.stores.length){toast('请先授权 Ozon 店铺',true);return}state.batchProcessHistoryMode=false;$('#batchProcessStore').innerHTML=storeOptions();const preferred=selectedStoreId();$('#batchProcessStore').value=state.stores.some(store=>store.store_id===preferred)?preferred:state.stores[0].store_id;$('#batchTargetStage').value=hasPermission('images.manage')?'4':'2';$('#batchTargetStage').querySelectorAll('option').forEach(option=>{option.disabled=Number(option.value)>=3&&!hasPermission('images.manage')});$('#batchProcessConfirm').checked=false;state.batchProcessJob=null;renderBatchProcess();updateBatchProcessFields();$('#batchProcessDialog').showModal()}
