async function startBatchProcess(event){event.preventDefault();try{const target=Number($('#batchTargetStage').value);if(target>=3&&!hasPermission('images.manage'))throw new Error('当前角色没有图片与 AI 处理权限');if(!$('#batchProcessConfirm').checked)throw new Error('请先确认允许调用外部接口');const dims=$('#batchDims').value.split('/').map(value=>Number(value.trim()));if(target>=4&&(dims.length!==4||dims.some(value=>!Number.isFinite(value)||value<=0)))throw new Error('默认尺寸必须是四个正数');const payload={pipeline_ids:[...state.selectedCatalogIds],target_stage:target,store_id:$('#batchProcessStore').value,confidence_threshold:Number($('#batchConfidence').value),media_mode:$('#batchMediaMode').value,text_mode:$('#batchTextMode').value,store_config:{cny_to_rub_rate:$('#batchRate').value.trim(),dimension_defaults:{depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'},vat:'0',attribute_overrides:{},sku_price_overrides:{}},confirm_external_requests:true};$('#submitBatchProcessBtn').disabled=true;state.batchProcessJob=await api('/api/batch-processes',{method:'POST',body:JSON.stringify(payload)});renderBatchProcess();toast('批量处理已进入后台队列；不会运行第五阶段');pollBatchProcess(state.batchProcessJob.job_id)}catch(error){$('#submitBatchProcessBtn').disabled=false;toast(error.message,true)}}
function researchDecisionName(value){return{NEW:'待审核',SHORTLISTED:'已收藏',APPROVED:'已通过',REJECTED:'已淘汰',SOURCED:'已找到货源'}[value]||value}
function emptyToNull(value){const text=String(value??'').trim();return text===''?null:text}
function researchRulesPayload(){const range=$('#researchPriceRange').value.split('/').map(value=>value.trim());return{date_from:$('#researchDateFrom').value,date_to:$('#researchDateTo').value,category:$('#researchCategory').value.trim(),brand_mode:$('#researchBrandMode').value,include_keywords:$('#researchInclude').value.trim(),exclude_keywords:$('#researchExclude').value.trim(),price_min_rub:emptyToNull(range[0]),price_max_rub:emptyToNull(range[1]),orders_min:emptyToNull($('#researchOrdersMin').value),revenue_min_rub:emptyToNull($('#researchRevenueMin').value),sellers_max:emptyToNull($('#researchSellersMax').value),rating_min:emptyToNull($('#researchRatingMin').value),reviews_min:emptyToNull($('#researchReviewsMin').value),growth_min_percent:emptyToNull($('#researchGrowthMin').value),max_candidates:Number($('#researchMaxCandidates').value)}}
function setResearchRules(rules){if(!rules){const today=new Date();const prior=new Date(today);prior.setDate(prior.getDate()-28);$('#researchDateFrom').value=prior.toISOString().slice(0,10);$('#researchDateTo').value=today.toISOString().slice(0,10);$('#researchRulesState').textContent='尚未保存';return}$('#researchDateFrom').value=rules.date_from||'';$('#researchDateTo').value=rules.date_to||'';$('#researchCategory').value=rules.category||'';$('#researchBrandMode').value=rules.brand_mode||'all';$('#researchInclude').value=rules.include_keywords||'';$('#researchExclude').value=rules.exclude_keywords||'';$('#researchPriceRange').value=rules.price_min_rub||rules.price_max_rub?`${rules.price_min_rub||''} / ${rules.price_max_rub||''}`:'';$('#researchOrdersMin').value=rules.orders_min||'';$('#researchRevenueMin').value=rules.revenue_min_rub||'';$('#researchSellersMax').value=rules.sellers_max||'';$('#researchRatingMin').value=rules.rating_min||'';$('#researchReviewsMin').value=rules.reviews_min||'';$('#researchGrowthMin').value=rules.growth_min_percent||'';$('#researchMaxCandidates').value=rules.max_candidates||100;$('#researchRulesState').textContent=`已保存 · ${rules.date_from} 至 ${rules.date_to}`}
function filteredResearch(){const query=state.researchSearch.toLowerCase();return(state.marketResearch.candidates||[]).filter(item=>{if(state.researchDecisionFilter!=='all'&&item.decision!==state.researchDecisionFilter)return false;if(!query)return true;return`${item.title||''} ${item.ozon_product_id||''} ${item.seller||''} ${item.category||''}`.toLowerCase().includes(query)})}
function renderResearch(){const summary=state.marketResearch.summary||{};$('#researchMetrics').innerHTML=[['候选商品',summary.total||0,'自动去重'],['待审核',summary.new||0,'等待运营判断'],['已收藏 / 通过',`${summary.shortlisted||0} / ${summary.approved||0}`,'进入货源匹配'],['已找到货源',summary.sourced||0,'已创建上架任务']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${hint}</small></article>`).join('');setResearchRules(state.marketResearch.rules);const rows=filteredResearch();$('#researchTable').innerHTML=rows.length?rows.map(item=>{const metrics=[item.price_rub?`${item.price_rub}₽`:'价格未知',item.orders?`订购 ${item.orders}`:'订购量未知',item.revenue_rub?`销售额 ${item.revenue_rub}₽`:''].filter(Boolean).join(' · ');const competition=[item.sellers?`${item.sellers} 个卖家`:'卖家数未知',item.rating?`评分 ${item.rating}`:'',item.reviews?`${item.reviews} 评论`:''].filter(Boolean).join(' · ');return`<tr><td><div class="catalog-product"><div class="catalog-thumb">${item.image_url?`<img src="${escapeHtml(item.image_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span>无图</span>'}</div><div><a href="${escapeHtml(item.product_url)}" target="_blank" rel="noopener noreferrer"><b>${escapeHtml(item.title)}</b></a><small>${escapeHtml(item.ozon_product_id||item.candidate_id)} · ${escapeHtml(item.category||'类目未知')}</small></div></div></td><td>${escapeHtml(metrics)}${item.growth_percent?`<small class="research-growth">增长 ${escapeHtml(item.growth_percent)}%</small>`:''}</td><td>${escapeHtml(competition)}<small>${escapeHtml(item.seller||'卖家未知')}</small></td><td><small>${escapeHtml((item.match_reasons||[]).join('；'))}</small></td><td><span class="research-status ${String(item.decision||'NEW').toLowerCase()}">${escapeHtml(researchDecisionName(item.decision))}</span>${item.pipeline_id?`<small>任务 ${escapeHtml(item.pipeline_id)}</small>`:''}</td><td>${escapeHtml(formatDate(item.updated_at))}</td><td><div class="catalog-row-actions"><button type="button" data-research-shortlist="${escapeHtml(item.candidate_id)}">${item.decision==='SHORTLISTED'?'取消收藏':'收藏'}</button><button type="button" data-research-source="${escapeHtml(item.candidate_id)}">${item.pipeline_id?'打开任务':'找 1688 货源'}</button><button type="button" data-research-reject="${escapeHtml(item.candidate_id)}">淘汰</button></div></td></tr>`}).join(''):'<tr><td colspan="7" class="table-empty">候选池为空。先保存规则，再使用 Ozon 选品插件同步商品。</td></tr>';document.querySelectorAll('[data-research-shortlist]').forEach(button=>button.onclick=()=>updateResearchCandidate(button.dataset.researchShortlist,{decision:(state.marketResearch.candidates.find(item=>item.candidate_id===button.dataset.researchShortlist)?.decision==='SHORTLISTED'?'NEW':'SHORTLISTED')}));document.querySelectorAll('[data-research-reject]').forEach(button=>button.onclick=()=>updateResearchCandidate(button.dataset.researchReject,{decision:'REJECTED'}));document.querySelectorAll('[data-research-source]').forEach(button=>button.onclick=()=>openResearchSource(button.dataset.researchSource))}
